try{const{startAlpine}=await import('./world.mjs');await startAlpine();}catch(error){const panel=document.getElementById('world-fatal');panel.hidden=false;document.getElementById('world-fatal-message').textContent=error.message.includes('WebGL')?'当前浏览器未能启动 WebGL 2。请使用支持三维图形的浏览器重新打开。':'小镇的必要资源没有载入，请重新打开。';document.getElementById('world-retry').addEventListener('click',()=>location.reload());console.error('Alpine world startup failed',error);}
